import time
import logging
import sys


class ConnectionOpenRecordFilter(logging.Filter):
    def filter(self, record):
        if hasattr(record, 'pkg_type'):
            if (record.pkg_type == 'O') and (len(record.getMessage()) == 0):
                return False  # ignore zero-length open-record
        return True


class RawFormatter(logging.Formatter):

    def formatTime(self, record, datefmt=None):
        '''
        Forces timestamp format to be as required for .raw.time logs
        (ignores datefmt)
        :param record: logrecord
        :param datefmt: ignored
        :return: timestamp string for .raw.time log
        '''
        ct = self.converter(record.created)
        integer_sec_timestamp = time.strftime("%H:%M:%S", ct)
        timestamp = "%s.%06d" % (integer_sec_timestamp, record.msecs)
        return timestamp

    def format(self, record):
        record.byte_length = len(record.getMessage()) + len("\n")  # \n will be added to each record logged
        if not hasattr(record, "pkg_type"):
            record.pkg_type = " " if record.direction == '<' else '>'
        if (record.pkg_type == 'O') and (len(record.getMessage()) == 0):
            record.byte_length = 0

        if self.usesTime():
            record.asctime = self.formatTime(record, self.datefmt)
        record.timestamp = self.formatTime(record, self.datefmt)
        record.epoch_time = "%s.%06d" % (str(record.created).split(".")[0], record.msecs)

        s = self._fmt % record.__dict__
        if record.exc_info:
            # Cache the traceback text to avoid converting it multiple times
            # (it's constant anyway)
            if not record.exc_text:
                record.exc_text = self.formatException(record.exc_info)
        if record.exc_text:
            if s[-1:] != "\n":
                s = s + "\n"
            try:
                s = s + record.exc_text
            except UnicodeError:
                s = s + record.exc_text.decode(sys.getfilesystemencoding(),
                                               'replace')
        return s
